import csv, re, sys, glob, os, json
from datetime import datetime
D='/Users/jonasstenglein/OtherProjects/StartMunichHack/ask-soony/data'
po={}
for r in csv.DictReader(open(D+'/raw/soony-data/soony/erp/purchase_orders_2025H2-2026.csv')):
    po[(r['po_number'],int(r['po_line']))]=dict(mat=r['material_id'],qty=float(r['quantity']),price=float(r['unit_price']),cur=r['currency'],prom=r['promised_date'],req=r['requested_date'],status=r['status'],inc=r['incoterm'],sup=r['supplier_id'],note=r['note'],odate=r['order_date'])
def d(s):
    return datetime.strptime(s,'%m/%d/%Y').strftime('%Y-%m-%d') if s else ''
for r in csv.DictReader(open(D+'/raw/soony-data/soony/erp/purchase_orders_legacy_2024-2025H1.csv'),delimiter=';'):
    po[(r['EBELN'],int(r['EBELP'])//10)]=dict(mat=r['MATNR'],qty=float(r['MENGE']),price=float(r['NETPR'].replace(',','.')),cur='?',prom=d(r['ZZCONF']),req=d(r['EINDT']),status=r['ZZSTAT'],inc='?',sup='SUP-%04d'%int(r['LIFNR']),note='',odate=d(r['BEDAT']))
item=re.compile(r'^\s*(\d{5})\s+(\S+)\s+.*?\s([\d,\.]+)\s+([\d\.,]+)\s+([A-Z]{3})\s+(\d{4}-\d{2}-\d{2})\s*$')
out=[]
for f in sorted(glob.glob(D+'/txt/suppliers/*/order_confirmations/*.txt')):
    t=open(f).read(); fn=os.path.basename(f)
    m=re.match(r'OA(\d+)_(\d+)',fn); conf,pon=m.groups()
    if len(t.strip())<20: print('EMPTY',fn); continue
    h=re.search(r'Your order (\d+) of (\S+) · Incoterms (.*?) · Payment\s*(\S+)',t.replace('\n',' '))
    issues=[]
    if h:
        if h.group(1)!=pon: issues.append(f'header PO {h.group(1)}')
        inc=h.group(3)
    else: issues.append('noheader'); inc=None
    lines=t.split('\n'); items=[]; last=0
    for i,l in enumerate(lines):
        mm=item.match(l)
        if mm: items.append(mm.groups()); last=i
    # remarks: lines after table that aren't description continuation
    rem=[]
    for l in lines[last+1:]:
        if l.strip() and not re.match(r'^\s{20,}',l): rem.append(l.strip())
    seen=set()
    for it,mat,qty,pr,cur,cd in items:
        ln=int(it)//10; seen.add(ln)
        p=po.get((pon,ln))
        if not p: issues.append(f'L{ln} not in SAP'); continue
        q=float(qty.replace(',','')); pr=float(pr)
        if mat!=p['mat']: issues.append(f"L{ln} mat {p['mat']}->{mat}")
        if q!=p['qty']: issues.append(f"L{ln} qty {p['qty']:.0f}->{q:.0f}")
        if abs(pr-p['price'])>1e-6: issues.append(f"L{ln} price {p['price']}->{pr}")
        if p['cur']!='?' and cur!=p['cur']: issues.append(f"L{ln} cur {p['cur']}->{cur}")
        if cd!=p['prom']: issues.append(f"L{ln} date SAP {p['prom']} OA {cd}")
        if inc and p['inc']!='?' and inc.strip()!=p['inc']: issues.append(f"L{ln} inc {p['inc']}->{inc}")
    for (pn,ln),p in po.items():
        if pn==pon and ln not in seen: issues.append(f'SAP L{ln} missing in OA')
    if not items: issues.append('NO ITEMS PARSED')
    st=','.join(sorted({po[(pon,l)]['status'] for l in seen if (pon,l) in po}))
    req=min([po[(pon,l)]['req'] for l in seen if (pon,l) in po] or [''])
    print(f"{fn} [{st} req{req}] {'; '.join(issues)}" + (f"\n   REM: {' | '.join(rem)}" if rem else ''))
